// Shared logic for the SEO answer pages.
// Single source of truth: seo-pages.json (+ content.json for the quiz cards).
// Generated outputs: answers/<slug>/index.html, answers/index.html, sitemap.xml.
// Never edit those generated files by hand: run `npm run generate:seo`.

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
export const GENERATED_MARK = "<!-- generated by scripts/generate-seo.mjs - do not edit by hand -->";

const STATUSES = ["draft", "ready", "live"];

export function loadSeo() {
  return JSON.parse(fs.readFileSync(path.join(ROOT, "seo-pages.json"), "utf8"));
}

export function loadContent() {
  return JSON.parse(fs.readFileSync(path.join(ROOT, "content.json"), "utf8"));
}

export function stripTags(html) {
  return String(html || "")
    .replace(/<[^>]+>/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&nbsp;/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export function esc(s) {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function jsonLd(obj) {
  return JSON.stringify(obj, null, 2).replace(/</g, "\\u003c");
}

/** Visible words of a page body (lead + sections + FAQ + note), used for the thin-content guard. */
export function countWords(page) {
  const parts = [page.lead];
  for (const s of page.sections || []) {
    parts.push(s.h2);
    for (const p of s.paragraphs || []) parts.push(p);
  }
  for (const f of page.faq || []) parts.push(f.q, f.a);
  parts.push(page.note);
  return stripTags(parts.filter(Boolean).join(" ")).split(" ").filter(Boolean).length;
}

/** Returns a list of human-readable problems (empty = valid). */
export function validate(seo, content) {
  const errors = [];
  const min = Number(seo.defaults?.minWordCount) || 0;
  const ids = new Set((content.items || []).map((i) => i.id));
  const slugs = new Set();

  for (const p of seo.pages || []) {
    const tag = `[${p.slug || "?"}]`;
    if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(p.slug || "")) errors.push(`${tag} invalid slug`);
    if (slugs.has(p.slug)) errors.push(`${tag} duplicate slug`);
    slugs.add(p.slug);
    if (!STATUSES.includes(p.status)) errors.push(`${tag} invalid status "${p.status}"`);
    if (p.status === "draft") continue;

    for (const k of ["title", "metaDescription", "h1", "lead", "updated"]) {
      if (!String(p[k] || "").trim()) errors.push(`${tag} missing ${k}`);
    }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(p.updated || "")) errors.push(`${tag} "updated" must be YYYY-MM-DD`);
    if (!Array.isArray(p.sections) || !p.sections.length) errors.push(`${tag} needs sections`);
    if (!Array.isArray(p.faq) || p.faq.length < 1) errors.push(`${tag} needs at least one FAQ entry`);
    if (!Array.isArray(p.sources) || p.sources.length < 1) errors.push(`${tag} needs at least one source`);
    for (const s of p.sources || []) {
      if (!/^https:\/\//.test(s.url || "") || !String(s.label || "").trim()) {
        errors.push(`${tag} source needs a label and an https url`);
      }
    }
    if (!Array.isArray(p.cardIds) || p.cardIds.length !== 3) errors.push(`${tag} needs exactly 3 cardIds`);
    for (const id of p.cardIds || []) {
      if (!ids.has(id)) errors.push(`${tag} cardId ${id} not found in content.json`);
    }
    if (!ids.has(p.questionId)) errors.push(`${tag} questionId ${p.questionId} not found in content.json`);
    const words = countWords(p);
    if (words < min) errors.push(`${tag} only ${words} visible words (minimum ${min})`);
  }
  return errors;
}

function head({ origin, siteName }, p, canonical, robots) {
  const ogImage = `${origin}/og-image.jpg`;
  return `<!DOCTYPE html>
<html lang="en">

<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">
  <meta name="theme-color" content="#38bdf8">
${robots ? `  <meta name="robots" content="${robots}">\n` : ""}  <title>${esc(p.title)}</title>
  <meta name="description" content="${esc(p.metaDescription)}">
  <link rel="canonical" href="${canonical}">
  <meta property="og:type" content="article">
  <meta property="og:site_name" content="${esc(siteName)}">
  <meta property="og:title" content="${esc(p.title)}">
  <meta property="og:description" content="${esc(p.metaDescription)}">
  <meta property="og:url" content="${canonical}">
  <meta property="og:image" content="${ogImage}">
  <meta name="twitter:card" content="summary_large_image">
  <meta name="twitter:image" content="${ogImage}">
  <link rel="icon" type="image/png" sizes="32x32" href="/icons/favicon-32x32.png">
  <link rel="icon" type="image/png" sizes="16x16" href="/icons/favicon-16x16.png">
  <link rel="icon" href="/icons/favicon.ico" sizes="any">
  <link rel="apple-touch-icon" href="/icons/brand-logo-512.png">
  <link rel="stylesheet" href="/style.css">
  <script data-goatcounter="https://breworfalse.goatcounter.com/count" async src="https://gc.zgo.at/count.js"></script>
`;
}

export function renderPage(seo, content, p) {
  const { origin, siteName } = seo.site;
  const canonical = `${origin}/answers/${p.slug}/`;
  const robots = p.status === "live" ? "" : "noindex";
  const byId = new Map(content.items.map((i) => [i.id, i]));
  const cta = `/?wt-source=seo-${p.slug}`;

  const ld = [
    {
      "@context": "https://schema.org",
      "@type": "FAQPage",
      mainEntity: p.faq.map((f) => ({
        "@type": "Question",
        name: stripTags(f.q),
        acceptedAnswer: { "@type": "Answer", text: stripTags(f.a) }
      }))
    },
    {
      "@context": "https://schema.org",
      "@type": "BreadcrumbList",
      itemListElement: [
        { "@type": "ListItem", position: 1, name: siteName, item: `${origin}/` },
        { "@type": "ListItem", position: 2, name: p.h1, item: canonical }
      ]
    }
  ];

  const sections = p.sections
    .map(
      (s) => `
          <h2 class="wt-h2">${esc(s.h2)}</h2>
${s.paragraphs.map((t) => `          <p>${t}</p>`).join("\n")}`
    )
    .join("\n");

  const faq = p.faq
    .map(
      (f) => `
          <h3 class="wt-h3">${f.q}</h3>
          <p>${f.a}</p>`
    )
    .join("\n");

  const cards = p.cardIds
    .map((id) => `            <li>${esc(byId.get(id).termEn)}</li>`)
    .join("\n");

  const sources = p.sources
    .map(
      (s) =>
        `            <li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)}</a>${
          s.note ? ` — ${esc(s.note)}` : ""
        }</li>`
    )
    .join("\n");

  return `${head(seo.site, p, canonical, robots)}${ld
    .map((o) => `  <script type="application/ld+json">\n${jsonLd(o)}\n  </script>\n`)
    .join("")}</head>

${GENERATED_MARK}
<body class="wt-page--doc">
  <div class="wt-app">
    <main class="wt-main">
      <div class="wt-container wt-container--doc">
        <article class="wt-card">
          <nav class="wt-doc-nav" aria-label="Breadcrumb">
            <a href="/" class="wt-btn wt-btn--ghost">Home</a>
          </nav>

          <h1 class="wt-h1">${esc(p.h1)}</h1>
          <p class="wt-press-lead">${p.lead}</p>
          <p class="wt-muted">Last checked: ${esc(p.updated)}</p>
${sections}

          <h2 class="wt-h2">Common questions</h2>
${faq}

          <h2 class="wt-h2">Test yourself</h2>
          <p>Three true-or-false cards from the quiz. Can you call them?</p>
          <ul>
${cards}
          </ul>
          <p><a class="wt-btn wt-btn--primary wt-btn--block" href="${cta}">Play Brew or False</a></p>

          <h2 class="wt-h2">Sources</h2>
          <ul>
${sources}
          </ul>
          <p class="wt-muted">${p.note}</p>
        </article>
      </div>
    </main>
  </div>
</body>
</html>
`;
}

export function renderHub(seo, pages) {
  const { origin, siteName } = seo.site;
  const canonical = `${origin}/answers/`;
  const p = {
    title: `Coffee Questions Answered | ${siteName}`,
    metaDescription: "Short, sourced answers to common true-or-false coffee questions."
  };
  const items = pages
    .map((x) => `            <li><a href="/answers/${x.slug}/">${esc(x.h1)}</a></li>`)
    .join("\n");
  return `${head(seo.site, p, canonical, "")}</head>

${GENERATED_MARK}
<body class="wt-page--doc">
  <div class="wt-app">
    <main class="wt-main">
      <div class="wt-container wt-container--doc">
        <article class="wt-card">
          <nav class="wt-doc-nav" aria-label="Breadcrumb">
            <a href="/" class="wt-btn wt-btn--ghost">Home</a>
          </nav>
          <h1 class="wt-h1">Coffee questions, answered</h1>
          <p class="wt-muted">Short answers with their sources. Then test yourself in the quiz.</p>
          <ul>
${items}
          </ul>
          <p><a class="wt-btn wt-btn--primary wt-btn--block" href="/?wt-source=seo-answers-hub">Play Brew or False</a></p>
        </article>
      </div>
    </main>
  </div>
</body>
</html>
`;
}

/** Map of repo-relative output path -> file content, for the whole generated set. */
export function buildOutputs(seo, content) {
  const out = new Map();
  const built = (seo.pages || []).filter((p) => p.status !== "draft");
  for (const p of built) out.set(`answers/${p.slug}/index.html`, renderPage(seo, content, p));
  const live = built.filter((p) => p.status === "live");
  if (live.length) out.set("answers/index.html", renderHub(seo, live));
  out.set("sitemap.xml", renderSitemap(seo, live));
  return out;
}

export function renderSitemap(seo, livePages) {
  const { origin } = seo.site;
  const urls = [...(seo.staticPages || [])].map((s) => ({ loc: `${origin}${s.path}`, lastmod: s.lastmod }));
  if (livePages.length) {
    const latest = livePages.map((p) => p.updated).sort().at(-1);
    urls.push({ loc: `${origin}/answers/`, lastmod: latest });
  }
  for (const p of livePages) urls.push({ loc: `${origin}/answers/${p.slug}/`, lastmod: p.updated });
  const body = urls
    .map((u) => `  <url>\n    <loc>${u.loc}</loc>\n    <lastmod>${u.lastmod}</lastmod>\n  </url>`)
    .join("\n\n");
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n\n${body}\n\n</urlset>\n`;
}

/** Generated dirs under answers/ that no longer correspond to a built page. */
export function staleDirs(outputs) {
  const dir = path.join(ROOT, "answers");
  if (!fs.existsSync(dir)) return [];
  const keep = new Set([...outputs.keys()].filter((k) => k.startsWith("answers/")).map((k) => k.split("/")[1]));
  return fs
    .readdirSync(dir, { withFileTypes: true })
    .filter((d) => d.isDirectory() && !keep.has(d.name))
    .map((d) => `answers/${d.name}`);
}
